// ---------- helpers ----------
const naira = n => '₦' + Number(n || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const num = n => Number(n || 0).toLocaleString('en-NG');
const today = $now.toFormat('dd/MM/yyyy');

// ---------- Sheet2: today's summary ----------
const summaryRows = $('Read sheet2').all().map(i => i.json);
const s = summaryRows.find(r => String(r['Date']) === today) || summaryRows[summaryRows.length - 1] || {};

// ---------- Sheet3: stock ----------
const stock = $('Read sheet3').all().map(i => i.json).filter(r => r['Product']);

const totalOpening  = stock.reduce((a, r) => a + Number(r['Opening Stock']  || 0), 0);
const totalReceived = stock.reduce((a, r) => a + Number(r['Stock Received'] || 0), 0);
const totalSold     = stock.reduce((a, r) => a + Number(r['Quantity Sold']  || 0), 0);
const totalClosing  = stock.reduce((a, r) => a + Number(r['Closing Stock']  || 0), 0);
const totalValue    = stock.reduce((a, r) => a + Number(r['Stock Value (₦)'] || 0), 0);

const color = st => st === 'Out of Stock' ? '#c62828' : st === 'Low' ? '#ef6c00' : '#2e7d32';
const alerts = stock.filter(r => ['Low', 'Out of Stock'].includes(r['Stock Status']));

const th = 'style="background:#0d47a1;color:#fff;padding:8px;text-align:left"';
const td = 'style="padding:8px;border-bottom:1px solid #ddd"';
const tdR = 'style="padding:8px;border-bottom:1px solid #ddd;text-align:right"';

// ---------- stock table rows ----------
const stockRows = stock.map(r => `
  <tr>
    <td ${td}>${r['Product']}</td>
    <td ${td}>${r['Category'] || ''}</td>
    <td ${td}>${r['Unit'] || ''}</td>
    <td ${tdR}>${num(r['Opening Stock'])}</td>
    <td ${tdR}>${num(r['Stock Received'])}</td>
    <td ${tdR}>${num(r['Quantity Sold'])}</td>
    <td ${tdR}><b>${num(r['Closing Stock'])}</b></td>
    <td ${tdR}>${naira(r['Stock Value (₦)'])}</td>
    <td ${td}><span style="color:${color(r['Stock Status'])};font-weight:bold">${r['Stock Status'] || '-'}</span></td>
  </tr>`).join('');

// ---------- alerts ----------
const alertHtml = alerts.length
  ? `<ul>${alerts.map(r => `<li><b>${r['Product']}</b>: ${r['Stock Status']} (closing stock: ${num(r['Closing Stock'])} ${r['Unit'] || ''})</li>`).join('')}</ul>`
  : `<p style="color:#2e7d32">No stock alerts today. All products are sufficient.</p>`;

// ---------- full email ----------
const html = `
<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:800px">
  <p>Hello Boss,</p>
  <p>I hope you had a great day of sales. Below is the daily sales and stock report for <b>${s['Date'] || today}</b>.</p>

  <h3 style="color:#0d47a1;border-bottom:2px solid #0d47a1;padding-bottom:4px">1. Sales Summary</h3>
  <table style="border-collapse:collapse;width:100%">
    <tr><th ${th}>Category</th><th ${th} style="background:#0d47a1;color:#fff;padding:8px;text-align:right">Amount</th></tr>
    <tr><td ${td}>Gas</td><td ${tdR}>${naira(s['Total Gas Sales (₦)'])}</td></tr>
    <tr><td ${td}>Cylinder</td><td ${tdR}>${naira(s['Total Cylinder Sales (₦)'])}</td></tr>
    <tr><td ${td}>Accessories</td><td ${tdR}>${naira(s['Total Accessories Sales (₦)'])}</td></tr>
    <tr><td ${td}>Equipment</td><td ${tdR}>${naira(s['Total Equipment Sales (₦)'])}</td></tr>
    <tr><td ${td}>Total Quantity Sold</td><td ${tdR}>${num(s['Total Quantity Sold'])}</td></tr>
    <tr style="background:#e3f2fd"><td ${td}><b>TOTAL SALES</b></td><td ${tdR}><b>${naira(s['TOTAL SALES (₦)'])}</b></td></tr>
  </table>

  <h3 style="color:#0d47a1;border-bottom:2px solid #0d47a1;padding-bottom:4px">2. Stock Report (Opening and Closing)</h3>
  <table style="border-collapse:collapse;width:100%;font-size:13px">
    <tr>
      <th ${th}>Product</th><th ${th}>Category</th><th ${th}>Unit</th>
      <th ${th}>Opening</th><th ${th}>Received</th><th ${th}>Sold</th>
      <th ${th}>Closing</th><th ${th}>Stock Value</th><th ${th}>Status</th>
    </tr>
    ${stockRows}
    <tr style="background:#e3f2fd;font-weight:bold">
      <td ${td} colspan="3">TOTAL</td>
      <td ${tdR}>${num(totalOpening)}</td>
      <td ${tdR}>${num(totalReceived)}</td>
      <td ${tdR}>${num(totalSold)}</td>
      <td ${tdR}>${num(totalClosing)}</td>
      <td ${tdR}>${naira(totalValue)}</td>
      <td ${td}></td>
    </tr>
  </table>

  <h3 style="color:#0d47a1;border-bottom:2px solid #0d47a1;padding-bottom:4px">3. Stock Alerts</h3>
  ${alertHtml}

  <p style="margin-top:24px">Regards,<br><b>EL-ENERGY GAS</b><br>Daily Report System</p>
  <p style="font-size:11px;color:#888">Report generated on ${$now.toFormat('dd/MM/yyyy')} at ${$now.toFormat('hh:mm a')}</p>
</div>`;

return [{
  json: {
    subject: `EL-ENERGY GAS Daily Sales & Stock Report - ${s['Date'] || today}`,
    html
  }
}];
